-- Cases de Corporate Finance: cf-simplificado (A nova linha de produção) e cf-complexo (A Linha 2 da Vale Verde). Todos os dados são fictícios.

INSERT INTO cases (id, title, area_id, summary, mission, context, content, status, island_order)
VALUES (
  $$cf-simplificado$$,
  $$CF simplificado: a nova linha de produção da Serra Azul$$,
  'corporate-finance',
  $$Atue como estagiária de FP&A e recomende ao conselho se a Laticínios Serra Azul deve comprar uma nova linha de produção de iogurte proteico.$$,
  $$Escolher as informações que importam, calcular o VPL, decidir como pagar, rever a recomendação diante de uma novidade e defendê-la diante de uma banca.$$,
  $$Você é estagiária de FP&A da Laticínios Serra Azul (empresa fictícia), em Minas Gerais. Na quinta-feira, o conselho vai decidir se compra uma nova linha de produção de iogurte proteico. Marina, a diretora financeira, pede: “Preciso da sua recomendação até quarta.” Ao longo da semana, você vai escolher as informações que importam, calcular se o investimento vale a pena, decidir como pagá-lo, rever a recomendação diante de uma novidade e defendê-la diante de uma banca. Todos os nomes, empresas e números são fictícios.$$,
  $${"resumo": "Corporate Finance é a área financeira dentro das empresas: decide em que investir, como pagar e como cuidar do caixa. Neste case rápido, você é estagiária de FP&A e recomenda se a Laticínios Serra Azul deve comprar uma nova linha de produção. A empresa e os números são fictícios.", "links": [], "cards": [{"titulo": "O que faz Corporate Finance", "texto": "Corporate Finance (finanças corporativas) é a área financeira dentro das empresas. Ela responde a três perguntas: em que investir (quais projetos valem a pena), como pagar (com caixa, dívida ou sócios) e como cuidar do dinheiro do dia a dia (caixa, contas a pagar e a receber).", "naPratica": "Diferente de quem assessora empresas de fora, a profissional trabalha dentro da empresa e vive as consequências das decisões."}, {"titulo": "Decidir se um investimento vale a pena", "texto": "O VPL traz todos os fluxos futuros a valor de hoje; a TIR é a taxa que zera o VPL; o payback é o tempo para recuperar o investimento. O WACC é o custo médio do dinheiro da empresa (dívida e capital dos sócios) e funciona como taxa mínima de retorno.", "naPratica": "Um projeto pode parecer bom por um critério e não criar valor por outro."}, {"titulo": "Como pagar: alavancagem e covenants", "texto": "Alavancagem é a dívida líquida dividida pelo EBITDA. Covenants são limites que os credores impõem, como “no máximo 2,5 vezes”. A dívida líquida é a dívida menos o caixa.", "naPratica": "A forma de pagar um investimento também pode mudar a margem da empresa até o limite dos bancos."}, {"titulo": "Lucro não é caixa", "texto": "A DRE mostra receita, custos e lucro; o balanço mostra o que a empresa tem e o que deve; o fluxo de caixa mostra o dinheiro que entrou e saiu. Uma empresa pode ter lucro e ficar sem dinheiro se vende a prazo e paga à vista.", "naPratica": "Por isso a análise de um projeto olha para o fluxo de caixa, não só para o lucro."}], "comoSeEntra": {"ondeSeTrabalha": "Dentro de empresas, como uma indústria, uma varejista ou uma empresa de tecnologia. As principais equipes são FP&A (planejamento e análise financeira), Tesouraria, Controladoria, Relações com Investidores (nas empresas listadas) e M&A corporativo.", "formacoes": "Pós-graduações e certificações (como o CFA) ajudam nas fases mais avançadas, mas não são exigidas para começar. Regras e certificações devem ser conferidas com uma profissional da área.", "vagas": "Estágio e analista júnior em áreas como FP&A, controladoria, contabilidade e controle financeiro. Na carreira, a estagiária atualiza planilhas e relatórios, faz conciliações e apoia o fechamento e o orçamento.", "oQueAjuda": "Excel e modelagem; contabilidade bem entendida; saber explicar números para quem não é de finanças; inglês, em multinacionais.", "quandoRecrutam": "Vagas fecham rápido: acompanhe com frequência as páginas de carreira das empresas e confira os requisitos de vagas de FP&A e Tesouraria para ver o que estudar primeiro."}}$$::jsonb,
  'publicado',
  9
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO cases (id, title, area_id, summary, mission, context, content, status, island_order)
VALUES (
  $$cf-complexo$$,
  $$CF completo: a Linha 2 da Vale Verde$$,
  'corporate-finance',
  $$Avalie se um investimento de R$ 20 milhões cria valor, compare três formas de financiá-lo e proponha como liberar caixa do capital de giro.$$,
  $$Avaliar se o projeto cria valor, recomendar como financiá-lo e propor como liberar caixa do capital de giro, em um memorando à diretora financeira.$$,
  $$Você trabalha como estagiária de FP&A da Embalagens Vale Verde (empresa fictícia), fabricante de embalagens de papelão para alimentos, com fábrica em Goiás. A diretoria quer investir R$ 20 milhões numa segunda linha de produção. Sua missão é avaliar se o projeto cria valor, recomendar como financiá-lo e propor como liberar caixa do capital de giro. Valores em R$ milhões, salvo indicação. Data-base: 31/12/2025. Todos os nomes, empresas e números são fictícios.$$,
  $${"resumo": "Em Corporate Finance, a analista de FP&A avalia se um investimento cria valor, compara formas de financiá-lo e procura caixa preso no capital de giro. Neste case, você avalia a segunda linha de produção da Embalagens Vale Verde, uma empresa fictícia, e entrega uma recomendação à diretora financeira.", "links": [], "cards": [{"titulo": "O que faz Corporate Finance", "texto": "Corporate Finance (finanças corporativas) é a área financeira dentro das empresas. Ela responde a três perguntas: em que investir (quais projetos valem a pena), como pagar (com caixa, dívida ou sócios) e como cuidar do dinheiro do dia a dia (caixa, contas a pagar e a receber).", "naPratica": "Diferente de quem assessora empresas de fora, a profissional trabalha dentro da empresa e vive as consequências das decisões."}, {"titulo": "Do EBITDA ao fluxo de caixa do projeto", "texto": "EBITDA é o resultado da operação antes de juros, impostos, depreciação e amortização, uma aproximação da geração de caixa operacional. Para avaliar um projeto, o fluxo de caixa considera também impostos, investimento (CAPEX) e o dinheiro preso em capital de giro.", "naPratica": "O EBITDA sozinho não diz se o projeto paga o investimento."}, {"titulo": "Decidir se um investimento vale a pena", "texto": "O VPL traz todos os fluxos futuros a valor de hoje; a TIR é a taxa que zera o VPL; o payback é o tempo para recuperar o investimento. O WACC é o custo médio do dinheiro da empresa (dívida e capital dos sócios) e funciona como taxa mínima de retorno.", "naPratica": "Um projeto pode parecer bom por um critério e não criar valor por outro."}, {"titulo": "Financiamento e capital de giro", "texto": "A empresa pode financiar um investimento com caixa, dívida ou sócios, e cada opção tem custo, prazo e efeito na alavancagem. Capital de giro é o dinheiro preso entre pagar fornecedores, manter estoque e receber dos clientes. Ciclo de caixa = prazo médio de recebimento + prazo médio de estoque − prazo médio de pagamento.", "naPratica": "Liberar caixa do capital de giro pode reduzir a necessidade de captar."}, {"titulo": "Variação, orçamento e business case", "texto": "Orçamento é o plano do ano e forecast é a atualização dele durante o ano. A análise de variação compara o realizado com o orçado e explica a diferença. Um business case de novo investimento reúne premissas, fluxo de caixa, VPL e TIR, sensibilidades, riscos e recomendação.", "naPratica": "Uma boa recomendação diz o que precisaria ser verdade para o projeto valer a pena."}], "comoSeEntra": {"ondeSeTrabalha": "Dentro de empresas, como uma indústria, uma varejista ou uma empresa de tecnologia. As principais equipes são FP&A (planejamento e análise financeira), Tesouraria, Controladoria, Relações com Investidores (nas empresas listadas) e M&A corporativo.", "formacoes": "Pós-graduações e certificações (como o CFA) ajudam nas fases mais avançadas, mas não são exigidas para começar. Regras e certificações devem ser conferidas com uma profissional da área.", "vagas": "Estágio e analista júnior em áreas como FP&A, controladoria, contabilidade e controle financeiro. Na carreira, a estagiária atualiza planilhas e relatórios, faz conciliações e apoia o fechamento e o orçamento.", "oQueAjuda": "Excel e modelagem; contabilidade bem entendida; saber explicar números para quem não é de finanças; inglês, em multinacionais.", "quandoRecrutam": "Vagas fecham rápido: acompanhe com frequência as páginas de carreira das empresas e confira os requisitos de vagas de FP&A e Tesouraria para ver o que estudar primeiro."}}$$::jsonb,
  'publicado',
  10
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO contents (id, title, type, area_id, summary, body, url, minutes, case_ids) VALUES
($$cf-vpl-tir-payback$$, $$VPL, TIR, payback e WACC$$, $$artigo$$, 'corporate-finance', $$Como decidir se um investimento vale a pena e por que o payback sozinho não basta.$$, $$O **VPL** (valor presente líquido) traz todos os fluxos futuros de um projeto a valor de hoje e subtrai o investimento: se for positivo, o projeto cria valor; se for negativo, destrói. A **TIR** é a taxa que zera o VPL, e deve ser comparada com a taxa mínima de retorno. O **payback** é o tempo para recuperar o investimento. Ele é simples de explicar, mas ignora o valor do dinheiro no tempo e o que acontece depois do prazo; por isso, sozinho, é um critério fraco. O **payback descontado** usa fluxos já trazidos a valor presente. O **WACC** é o custo médio do dinheiro da empresa (dívida e capital dos sócios) e é usado como taxa de desconto, isto é, o retorno mínimo que o projeto precisa entregar. Receber R$ 1 daqui a alguns anos vale menos do que receber R$ 1 hoje, e é essa diferença que o desconto mede. Em planilha, as funções VPL, TIR, XVPL e XTIR e as tabelas de sensibilidade ajudam a testar premissas.$$, NULL, 6, $$["cf-simplificado", "cf-complexo"]$$::jsonb),
($$cf-alavancagem-covenant$$, $$Dívida líquida, alavancagem e covenants$$, $$artigo$$, 'corporate-finance', $$Como a forma de pagar um investimento muda a alavancagem e a relação com os bancos.$$, $$**Dívida líquida** é a dívida menos o caixa. Por isso, usar caixa para pagar um investimento também aumenta a dívida líquida, assim como tomar um empréstimo. A **alavancagem** é a dívida líquida dividida pelo EBITDA e indica quantos anos de geração de caixa operacional seriam necessários para pagar a dívida; os bancos olham para ela para medir a capacidade de pagamento. **Covenants** são limites contratuais que os credores impõem, como “no máximo 2,5 vezes”. Se um covenant for quebrado, o credor pode antecipar o vencimento da dívida ou exigir renegociação. Na hora de escolher entre dívida e caixa próprio, compare custo, prazo, flexibilidade, alavancagem e o efeito de cada opção na dívida líquida. Dividir um investimento em fases e conversar antes com os bancos são formas de reduzir o risco.$$, NULL, 6, $$["cf-simplificado", "cf-complexo"]$$::jsonb),
($$cf-fluxo-de-caixa-livre$$, $$Do EBITDA ao fluxo de caixa de um projeto$$, $$artigo$$, 'corporate-finance', $$Como montar o fluxo de caixa livre de um projeto a partir da receita adicional.$$, $$O fluxo de caixa de um projeto parte da **receita adicional** e da margem EBITDA esperada. Do EBITDA, subtraia a **depreciação** para chegar ao **EBIT**; os **impostos** incidem sobre o EBIT. Como a depreciação não é saída de caixa, ela não entra no fluxo; o que entra é a economia de imposto que ela gera. O **capital de giro** do projeto (estoque e contas a receber, menos fornecedores) prende caixa enquanto a receita cresce: o que conta no fluxo de cada ano é a **variação** do capital de giro, e ele costuma ser recuperado ao fim do projeto. O **investimento** (CAPEX) sai no ano zero. Ao fim do horizonte pode haver um **valor residual** do ativo. Todos esses fluxos, ao fim de cada ano, são trazidos a valor presente pelo WACC. Teste sempre como o resultado muda se o preço ou a taxa de desconto mudarem (análise de sensibilidade). A depreciação, como todo custo, afeta o lucro e o balanço, mas o efeito no caixa vem só pelo imposto.$$, NULL, 7, $$["cf-complexo"]$$::jsonb),
($$cf-capital-de-giro$$, $$Capital de giro e ciclo de caixa$$, $$glossario$$, 'corporate-finance', $$O dinheiro preso entre pagar fornecedores, manter estoque e receber dos clientes.$$, $$**Capital de giro** é o dinheiro preso entre pagar fornecedores, manter estoque e receber dos clientes. Quando a empresa cresce, precisa de mais estoque e de mais contas a receber antes de o dinheiro entrar, e por isso o crescimento consome caixa. O **ciclo de caixa** é o prazo médio de recebimento mais o prazo médio de estoque menos o prazo médio de pagamento. Quanto menor o ciclo, menos caixa fica preso. Formas de reduzi-lo: negociar prazos com fornecedores, reduzir estoque e antecipar recebíveis. Cada ação tem um risco: alongar o prazo de pagamento pode estressar a relação com fornecedores; estoque menor pode causar falta de produto; antecipar recebíveis tem custo financeiro. Uma estimativa aproximada do capital de giro é a receita diária multiplicada pelos dias do ciclo de caixa.$$, NULL, 5, $$["cf-complexo"]$$::jsonb),
($$cf-fontes-de-estudo$$, $$Onde estudar finanças corporativas$$, $$artigo$$, 'corporate-finance', $$Livros, aulas e fontes gratuitas para os conceitos, a prática com empresas reais e a carreira.$$, $$**Para os conceitos e o case:** o livro “Administração Financeira” (Ross, Westerfield, Jaffe e Lamb) traz a base de VPL, TIR, custo de capital e estrutura de capital. O livro “Finanças Corporativas e Valor” (Alexandre Assaf Neto) é a referência brasileira, com exemplos do mercado local. As aulas gratuitas de finanças corporativas do professor Aswath Damodaran estão em inglês, com legendas automáticas, no site e no canal dele no YouTube. Os artigos gratuitos do Corporate Finance Institute (CFI) tratam de capital de giro, VPL e modelagem (em inglês). No Excel, pratique as funções VPL, TIR, XVPL e XTIR e as tabelas de sensibilidade.

**Para treinar com empresas reais:** use as apresentações de resultados nos sites de Relações com Investidores das empresas listadas: escolha uma empresa e explique a variação do trimestre. O Portal do Investidor da CVM e o Bora Investir, da B3, explicam conceitos de mercado em linguagem simples.

**Para a carreira:** guias salariais de consultorias de recrutamento (como Robert Half e Michael Page) ajudam a entender cargos e faixas. Ler os requisitos de vagas de FP&A e Tesouraria no LinkedIn mostra o que estudar primeiro (Excel, Power BI, inglês).$$, NULL, 5, $$["cf-simplificado", "cf-complexo"]$$::jsonb)
ON CONFLICT (id) DO NOTHING;

